class Solution:
    def amountPainted(self, paint: List[List[int]]) -> List[int]:
        limit = max(e for _, e in paint)
        painted = bytearray(limit)
        res = []
        for s, e in paint:
            fresh = 0
            for x in range(s, e):
                if not painted[x]:
                    painted[x] = 1
                    fresh += 1
            res.append(fresh)
        return res

