class Solution {
public:
    vector<int> amountPainted(vector<vector<int>>& paint) {
        int limit = 0;
        for (auto& p : paint) limit = max(limit, p[1]);
        vector<bool> painted(limit, false);
        vector<int> res;
        for (auto& p : paint) {
            int fresh = 0;
            for (int x = p[0]; x < p[1]; ++x)
                if (!painted[x]) { painted[x] = true; ++fresh; }
            res.push_back(fresh);
        }
        return res;
    }
};

