class Solution {
    public int[] amountPainted(int[][] paint) {
        int limit = 0;
        for (int[] p : paint) limit = Math.max(limit, p[1]);
        boolean[] painted = new boolean[limit];
        int[] res = new int[paint.length];
        for (int d = 0; d < paint.length; d++) {
            int fresh = 0;
            for (int x = paint[d][0]; x < paint[d][1]; x++)
                if (!painted[x]) { painted[x] = true; fresh++; }
            res[d] = fresh;
        }
        return res;
    }
};

