class Solution {
public:
    vector<int> amountPainted(vector<vector<int>>& paint) {
        map<int, int> painted;
        vector<int> res;
        res.reserve(paint.size());
        for (auto& iv : paint) {
            int s0 = iv[0], e0 = iv[1];
            int covered = 0, s = s0, e = e0;
            auto it = painted.lower_bound(s0);
            if (it != painted.begin()) {
                auto pv = prev(it);
                if (pv->second > s0) it = pv;
            }
            while (it != painted.end() && it->first < e0) {
                covered += min(e0, it->second) - max(s0, it->first);
                s = min(s, it->first);
                e = max(e, it->second);
                it = painted.erase(it);
            }
            painted[s] = e;
            res.push_back(e0 - s0 - covered);
        }
        return res;
    }
};

