class Solution {
    public int[] amountPainted(int[][] paint) {
        TreeMap<Integer, Integer> painted = new TreeMap<>();
        int[] res = new int[paint.length];
        for (int d = 0; d < paint.length; d++) {
            int s0 = paint[d][0], e0 = paint[d][1];
            int covered = 0, s = s0, e = e0;
            Map.Entry<Integer, Integer> cur = painted.floorEntry(s0);
            if (cur == null || cur.getValue() <= s0)
                cur = cur == null ? painted.firstEntry() : painted.higherEntry(cur.getKey());
            while (cur != null && cur.getKey() < e0) {
                covered += Math.min(e0, cur.getValue()) - Math.max(s0, cur.getKey());
                s = Math.min(s, cur.getKey());
                e = Math.max(e, cur.getValue());
                int key = cur.getKey();
                painted.remove(key);
                cur = painted.higherEntry(key);
            }
            painted.put(s, e);
            res[d] = e0 - s0 - covered;
        }
        return res;
    }
};

