var amountPainted = function(paint) {
    const starts = [], ends = [], res = [];
    const lowerBound = (arr, x) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < x) lo = mid + 1; else hi = mid;
        }
        return lo;
    };
    for (const [s0, e0] of paint) {
        let covered = 0;
        const i = lowerBound(ends, s0);
        let j = i;
        while (j < starts.length && starts[j] < e0) {
            covered += Math.min(e0, ends[j]) - Math.max(s0, starts[j]);
            j++;
        }
        let ns = s0, ne = e0;
        if (j > i) { ns = Math.min(ns, starts[i]); ne = Math.max(ne, ends[j - 1]); }
        starts.splice(i, j - i, ns);
        ends.splice(i, j - i, ne);
        res.push(e0 - s0 - covered);
    }
    return res;
};
